    # Use a dynamic threshold based on round number
    # Early rounds: more trusting; later rounds: stricter
    threshold = 0.4 - 0.002 * round_num  # starts at 0.4, drops slowly
    threshold = max(0.1, min(0.5, threshold))  # keep between 0.1 and 0.5
    if recipient_reputation > threshold:
        return True
    else:
        # If the recipient's reputation is low but we have been cooperative often,
        # give a second chance (not direct reciprocity, just our own history)
        if my_history:
            my_coops = sum(1 for h in my_history if h['action'] == 'cooperate')
            if my_coops > round_num * 0.6:  # I've been generally cooperative
                return True
        return False

